"""Gcode normalisation for byte comparisons. Only the Orca timestamp line is removed."""

import re

# Orca writes "; generated by OrcaSlicer 2.4.2 on 2026-11-03 at 11:04:31" as line 2 of the header.
_TIMESTAMP = re.compile(rb"^; generated by OrcaSlicer [^\r\n]* on [^\r\n]*(?:\r\n|\n|\r)?", re.MULTILINE)


def normalize_gcode(data):
    """Return the gcode with the Orca timestamp line removed and every other byte unchanged.

    Accepts bytes or str and returns the same type.
    """
    if isinstance(data, str):
        return normalize_gcode(data.encode("utf-8")).decode("utf-8")
    return _TIMESTAMP.sub(b"", data)
